// ==== What it does ====
// Turns a stream of machine state-change events into a list of stops with start, end and duration, and separates
// real stoppages from micro-stops. Each event row means 'the machine entered this state at this time and stays in it
// until the next event of the same machine'. The last event of every machine is open: it lasts until 'asOf', and the
// result marks it as StillStopped, so a machine that is down right now shows up even though no end event exists yet.
// Typical use: a Real-Time Dashboard tile 'machines stopped for 5 minutes or more', or the first step of a downtime Pareto.

// ==== Required tables/columns (assumed schema, adjust names to your Eventhouse) ====
// MachineState: one row per state change, delivered by an eventstream or an edge gateway.
//   Timestamp:datetime  time of the state change (UTC; datetime in KQL is always UTC)
//   MachineId:string    asset identifier, for example the machine number from your asset list
//   State:string        'Running', 'Stopped', 'Fault', 'Setup', 'PlannedStop' (your own state list; map PLC codes in ingestion)
//   ReasonCode:string   reason selected by the operator or the PLC alarm code, empty while running
// Needs a KQL queryset or Real-Time Dashboard on a KQL database in a Microsoft Fabric Eventhouse. The query uses only
// standard KQL operators (sort, serialize, next, summarize, datatable), so it also runs on Azure Data Explorer.

// ==== Query ====
// The sample table below is defined inline with let, so the query runs as it is. To use it on live data delete the
// 'let MachineState = datatable(...)' statement and set asOf to now().
// ---- Parameters -----------------------------------------------------------
let asOf       = datetime(2026-03-02 14:00:00);   // sample time; use now() on live data
let minStopMin = 5.0;                             // at least this long = Stoppage, shorter = MicroStop
let stopStates = dynamic(["Stopped", "Fault"]);   // states that count as a stop; Setup and PlannedStop are handled elsewhere
let MachineState = datatable(Timestamp:datetime, MachineId:string, State:string, ReasonCode:string) [
  datetime(2026-03-02 06:00:00), "M1", "Running", "",
  datetime(2026-03-02 07:10:00), "M1", "Stopped", "TOOL_CHANGE",
  datetime(2026-03-02 07:14:00), "M1", "Running", "",
  datetime(2026-03-02 09:00:00), "M1", "Fault", "SPINDLE_ALARM",
  datetime(2026-03-02 09:47:00), "M1", "Running", "",
  datetime(2026-03-02 12:00:00), "M1", "Stopped", "NO_OPERATOR",
  datetime(2026-03-02 06:00:00), "M2", "Running", "",
  datetime(2026-03-02 08:30:00), "M2", "Stopped", "MATERIAL",
  datetime(2026-03-02 08:33:00), "M2", "Running", "",
  datetime(2026-03-02 10:00:00), "M2", "Setup", "CHANGEOVER",
  datetime(2026-03-02 10:45:00), "M2", "Running", "",
  datetime(2026-03-02 13:55:00), "M2", "Stopped", "MATERIAL"
];
// ---------------------------------------------------------------------------
MachineState
| where Timestamp <= asOf
// Order per machine; sort marks the rows as serialized, so next() works
| sort by MachineId asc, Timestamp asc
| serialize
// Optional for chatty sources that repeat the same state every few seconds: keep only real changes
// | where MachineId != prev(MachineId, 1, "") or State != prev(State, 1, "")
| extend IsLastEvent = next(MachineId, 1, "") != MachineId
| extend EndTime = iff(IsLastEvent, asOf, next(Timestamp))
// Subtracting datetimes gives a timespan; dividing by 1m gives minutes as a real number. Do not round before comparing.
| extend DurationMin = (EndTime - Timestamp) / 1m
| where State in (stopStates) and DurationMin > 0
| extend Kind = iff(DurationMin >= minStopMin, "Stoppage", "MicroStop")
| project MachineId, StartTime = Timestamp, EndTime, State, ReasonCode, DurationMin = round(DurationMin, 1), Kind, StillStopped = IsLastEvent
| order by MachineId asc, StartTime asc

// ==== Worked example (the sample data above; the numbers were computed independently of the query) ====
// Columns: MachineId, StartTime, EndTime, State, ReasonCode, DurationMin, Kind, StillStopped
//   M1  07:10  07:14  Stopped  TOOL_CHANGE        4.0  MicroStop  false
//   M1  09:00  09:47  Fault    SPINDLE_ALARM     47.0  Stoppage   false
//   M1  12:00  14:00  Stopped  NO_OPERATOR      120.0  Stoppage   true
//   M2  08:30  08:33  Stopped  MATERIAL           3.0  MicroStop  false
//   M2  13:55  14:00  Stopped  MATERIAL           5.0  Stoppage   true
// M2 at 13:55 is open and lasts exactly 5.0 minutes until asOf. Because the test is >= minStopMin it counts as a
// Stoppage. With > it would silently drop. Always decide on purpose whether the limit itself belongs to the class.
// The Setup block of M2 (10:00-10:45) is not in stopStates, so it does not appear here.

// ==== Summary per machine (replace the last two lines of the query, project and order, with this) ====
// | summarize Stoppages = countif(Kind == "Stoppage"), StoppageMin = round(sumif(DurationMin, Kind == "Stoppage"), 1),
//             MicroStops = countif(Kind == "MicroStop"), MicroStopMin = round(sumif(DurationMin, Kind == "MicroStop"), 1),
//             LongestMin = round(max(DurationMin), 1) by MachineId
// Result for the sample:
//   M1  Stoppages=2  StoppageMin=167.0  MicroStops=1  MicroStopMin=4.0  LongestMin=120.0
//   M2  Stoppages=1  StoppageMin=5.0  MicroStops=1  MicroStopMin=3.0  LongestMin=5.0
// For a reason Pareto use: | summarize Events = count(), TotalMin = round(sum(DurationMin), 1) by ReasonCode | order by TotalMin desc

// ==== How to adapt ====
// minStopMin: pick the value from your own stop definition; micro-stops are usually
//   analysed separately because they are frequent and hide in the Performance factor of OEE.
// stopStates: add 'NoOperator' or 'Starved' if your control system reports them as separate states.
// Live status tile: keep only rows where StillStopped is true and DurationMin >= minStopMin.
// Shift or day reports: bin the StartTime with bin(StartTime, 1d) and summarize; for stops that cross a boundary use the
//   day-split pattern from the OEE availability entry, otherwise a night-time stop is booked wholly to the day it started.
// Alerts: an alert on 'StillStopped and DurationMin >= minStopMin' can be wired to a notification with Fabric Activator;
//   check the current Activator documentation for the supported sources before you build it.

// ==== Performance notes ====
// Filter on Timestamp first and keep the window small (a few days or the current shift); sort is the expensive step.
// The query reads every state change of the window, so it scales with events, not with sensors. For history older than
//   a few weeks, store the computed intervals in a separate table (update policy or scheduled job) and query that table.

// ==== Common mistakes ====
// Forgetting that the last event of a machine has no successor: without the IsLastEvent branch the current stop is lost,
//   because next(Timestamp) is null and the duration becomes null.
// Rounding the duration and then comparing: 4.96 rounds to 5.0 and flips from MicroStop to Stoppage. Round for display only.
// Using now() inside a saved dashboard query and comparing results with a report built at another time: now() moves.
// Treating events that arrive late as ordered: if gateways buffer data, sort by the event time and not by ingestion time.
// Mixing a machine that is switched off (no events at all) with a machine that is running: no events means no row, so add a
//   heartbeat or a last-seen check if silence must raise an alarm.

// ==== Privacy and safety ====
// Machine states are not personal data, but a ReasonCode like 'NO_OPERATOR' combined with shift and machine can point to a
//   person. Keep operator names and badge numbers out of the table; involve the works council before you publish reports
//   that compare individuals or small teams.
// This query supports analysis and alarms. It is not a safety function, and in aerospace or MRO environments it does not
//   replace the records that your quality system and certifying staff require for the work performed.

// ==== What it does ====
// Calculates the Availability factor of OEE per machine and per day from state-change events:
//   Availability = run time / planned production time
//   planned production time = length of the planned shift window minus planned stops (breaks, planned maintenance)
// Every state interval is cut at midnight (day split), clipped to the shift window of that day and clipped to 'asOf', so a
// stop that begins before the shift or runs over midnight is counted only for the part that lies inside the window.
// A Coverage column shows how much of the window is covered by events; below 1.0 means missing data, not low availability.
// Definition used here: changeover (Setup) and faults are availability losses, only 'PlannedStop' is excluded from the
// planned production time. Plants differ; write your choice into your OEE definition sheet and change plannedStates.

// ==== Required tables/columns (assumed schema) ====
// MachineState: one row per state change.
//   Timestamp:datetime, MachineId:string, State:string ('Running', 'Stopped', 'Fault', 'Setup', 'PlannedStop')
// The state in force at the start of the window must be in the data: the sample includes the 22:00 'Running' event from the
// evening before. On live data read from some days before fromDay (for example fromDay minus 2 days) and filter later.
// datetime is UTC in KQL. The shift window below is therefore in UTC; shift it by your UTC offset or maintain a shift table.

// ==== Query ====
// ---- Parameters -----------------------------------------------------------
let asOf          = datetime(2026-03-03 12:00:00);   // sample time; use now() on live data
let fromDay       = datetime(2026-03-02);        // first day in the report (midnight)
let shiftStart    = 6h;                          // window start as offset from midnight
let shiftEnd      = 14h;                         // window end as offset from midnight
let plannedStates = dynamic(["PlannedStop"]);
let runStates     = dynamic(["Running"]);
let MachineState = datatable(Timestamp:datetime, MachineId:string, State:string) [
  datetime(2026-03-01 22:00:00), "M1", "Running",
  datetime(2026-03-02 07:00:00), "M1", "Fault",
  datetime(2026-03-02 08:00:00), "M1", "Running",
  datetime(2026-03-02 10:00:00), "M1", "PlannedStop",
  datetime(2026-03-02 10:30:00), "M1", "Running",
  datetime(2026-03-02 13:00:00), "M1", "Setup",
  datetime(2026-03-02 14:30:00), "M1", "Running",
  datetime(2026-03-03 05:00:00), "M1", "Fault",
  datetime(2026-03-03 07:00:00), "M1", "Running",
  datetime(2026-03-02 06:00:00), "M2", "Running",
  datetime(2026-03-02 09:00:00), "M2", "Stopped",
  datetime(2026-03-02 09:20:00), "M2", "Running"
];
// ---------------------------------------------------------------------------
MachineState
| where Timestamp <= asOf
| sort by MachineId asc, Timestamp asc
| serialize
| extend End = iff(next(MachineId, 1, "") == MachineId, next(Timestamp), asOf)
| where End > Timestamp
// One row per calendar day touched by the interval [Timestamp, End). End minus 1 ms keeps an interval that ends exactly at
// midnight from creating an empty extra day. range() includes its stop value.
| extend DayList = range(bin(Timestamp, 1d), bin(End - 1ms, 1d), 1d)
| mv-expand DayList
| extend Day = todatetime(DayList)
| where Day >= fromDay
| extend WinStart = Day + shiftStart,
         WinEnd   = iff(Day + shiftEnd < asOf, Day + shiftEnd, asOf)   // do not count hours that have not happened yet
| where WinEnd > WinStart
| extend ClipStart = max_of(Timestamp, WinStart),
         ClipEnd   = iff(End < WinEnd, End, WinEnd)
| extend ClipMin = max_of(0.0, (ClipEnd - ClipStart) / 1m)
| where ClipMin > 0
| summarize CoveredMin       = sum(ClipMin),
            RunMin           = sumif(ClipMin, State in (runStates)),
            PlannedStopMin   = sumif(ClipMin, State in (plannedStates)),
            WindowMin        = max((WinEnd - WinStart) / 1m)
            by MachineId, Day
| extend PlannedProductionMin = WindowMin - PlannedStopMin
| extend Availability = round(RunMin / PlannedProductionMin, 4),
         Coverage     = round(CoveredMin / WindowMin, 4)
| project MachineId, Day, WindowMin, PlannedStopMin, PlannedProductionMin, RunMin, Availability, Coverage
| order by MachineId asc, Day asc

// ==== Worked example (computed independently of the query) ====
// Window 06:00-14:00 = 480 min; on the last day the window ends at asOf 12:00 = 360 min.
//   M1  2026-03-02  Window=480  PlannedStop=30  PlannedProd=450  Run=330  Availability=0.7333  Coverage=1.0000
//   M1  2026-03-03  Window=360  PlannedStop=0  PlannedProd=360  Run=300  Availability=0.8333  Coverage=1.0000
//   M2  2026-03-02  Window=480  PlannedStop=0  PlannedProd=480  Run=460  Availability=0.9583  Coverage=1.0000
//   M2  2026-03-03  Window=360  PlannedStop=0  PlannedProd=360  Run=360  Availability=1.0000  Coverage=1.0000
// Check M1 on 2026-03-02: Running 06:00-07:00 is carried over from the evening before (60), 08:00-10:00 (120) and
// 10:30-13:00 (150) = 330 min. Fault 07:00-08:00 = 60, PlannedStop 10:00-10:30 = 30, Setup 13:00-14:30 is clipped at 14:00 = 60.
// 330 / (480 - 30) = 0.7333. On 2026-03-03 the fault from 05:00 is clipped at 06:00 and counts only 60 minutes until 07:00:
// 300 / 360 = 0.8333. M2 has no PlannedStop, so 460 / 480 = 0.9583.

// ==== How to adapt ====
// Several shifts per day: run the same logic with a small shift table (ShiftName, StartOffset, EndOffset) and cross join it to
//   the day rows before clipping; summarize by MachineId, Day, ShiftName.
// Plant hours in local time: add the UTC offset to shiftStart and shiftEnd, and mind daylight saving days (23 or 25 hours).
// Days without planned production (weekends): remove them with a calendar table or with dayofweek(Day) filters.
// Roll up to the line: summarize RunMin and PlannedProductionMin first and divide afterwards. Never average the daily
//   availability percentages of several machines, because machines with a short window would weigh the same as long ones.
// Combine with Performance and Quality in Power BI or in a second KQL query to get OEE = Availability x Performance x Quality.

// ==== Performance notes ====
// The day split multiplies rows by the number of days an interval spans; intervals that last weeks (a machine that is simply
//   switched off) create many rows. Keep the read window short and ignore states that are not relevant.
// For daily reporting, a materialized view or a scheduled job that stores the finished days is cheaper than recomputing.

// ==== Common mistakes ====
// Not reading the state that was already in force when the window started: the first hours of the day then have no row and
//   availability looks too low. Use the Coverage column to find this.
// Clipping the end but not the start (or the other way round): an overnight stop would be booked in full to one day.
// Using datetime_diff('minute', ...) for durations: it counts crossed minute boundaries, not elapsed time, so 4 min 2 s can
//   return 5. Subtract the datetimes and divide by 1m instead.
// Forgetting the open last interval: a machine that has been running since yesterday has no end event; the asOf branch
//   closes it.
// Treating missing data as downtime or as uptime without saying so; show Coverage next to the percentage.

// ==== Privacy and safety ====
// The result is machine data without personal data. If you add shift names, do not add the operators of the shift, and agree
//   with the works council how availability figures per machine and shift may be used.
// Availability from state events is an analysis figure. For customer or authority reporting use the definitions and records
//   your quality system prescribes.

// ==== What it does ====
// Finds abnormal vibration on machine spindles, pumps or fans in two ways on the same telemetry table:
//   A) Learned baseline: make-series builds an hourly series per machine and series_decompose_anomalies flags points that do
//      not fit the machine's own normal level (and its daily or weekly rhythm when enough history exists).
//   B) Plain statistics: mean and standard deviation of a reference period, then a z-score for every later reading. It needs
//      no model, is easy to explain to maintenance staff and can be checked by hand.
// Both return a list of suspicious readings. They are screening queries for condition monitoring. Alarm limits for the
// machine come from its documentation or your condition-monitoring specification, not from this query.

// ==== Required tables/columns (assumed schema) ====
// MachineTelemetry: one row per reading.
//   Timestamp:datetime, MachineId:string, Signal:string (here 'VibrationRms', velocity RMS in mm/s), Value:real
// The sample holds one reading per hour for two machines on 2026-03-02. M1 has two disturbed hours (17:00 and 18:00).
// Needs a KQL queryset on a KQL database in a Fabric Eventhouse; series_decompose_anomalies and make-series are standard KQL.

// ==== Query A: learned baseline per machine ====
// ---- Parameters -----------------------------------------------------------
let fromTime  = datetime(2026-03-02 00:00:00);
let toTime    = datetime(2026-03-03 00:00:00);   // make-series 'to' is exclusive
let binSize   = 1h;                              // use 10m for 1 Hz or 1 minute raw data
let threshold = 3.0;                             // series_decompose_anomalies k value; the default 1.5 is much more sensitive
let MachineTelemetry = datatable(Timestamp:datetime, MachineId:string, Signal:string, Value:real) [
  datetime(2026-03-02 00:00:00), "M1", "VibrationRms", 1.82,
  datetime(2026-03-02 01:00:00), "M1", "VibrationRms", 1.79,
  datetime(2026-03-02 02:00:00), "M1", "VibrationRms", 1.85,
  datetime(2026-03-02 03:00:00), "M1", "VibrationRms", 1.81,
  datetime(2026-03-02 04:00:00), "M1", "VibrationRms", 1.78,
  datetime(2026-03-02 05:00:00), "M1", "VibrationRms", 1.84,
  datetime(2026-03-02 06:00:00), "M1", "VibrationRms", 1.80,
  datetime(2026-03-02 07:00:00), "M1", "VibrationRms", 1.83,
  datetime(2026-03-02 08:00:00), "M1", "VibrationRms", 1.79,
  datetime(2026-03-02 09:00:00), "M1", "VibrationRms", 1.82,
  datetime(2026-03-02 10:00:00), "M1", "VibrationRms", 1.85,
  datetime(2026-03-02 11:00:00), "M1", "VibrationRms", 1.81,
  datetime(2026-03-02 12:00:00), "M1", "VibrationRms", 1.80,
  datetime(2026-03-02 13:00:00), "M1", "VibrationRms", 1.84,
  datetime(2026-03-02 14:00:00), "M1", "VibrationRms", 1.78,
  datetime(2026-03-02 15:00:00), "M1", "VibrationRms", 1.83,
  datetime(2026-03-02 16:00:00), "M1", "VibrationRms", 1.81,
  datetime(2026-03-02 17:00:00), "M1", "VibrationRms", 4.92,
  datetime(2026-03-02 18:00:00), "M1", "VibrationRms", 4.35,
  datetime(2026-03-02 19:00:00), "M1", "VibrationRms", 1.82,
  datetime(2026-03-02 20:00:00), "M1", "VibrationRms", 1.80,
  datetime(2026-03-02 21:00:00), "M1", "VibrationRms", 1.84,
  datetime(2026-03-02 22:00:00), "M1", "VibrationRms", 1.79,
  datetime(2026-03-02 23:00:00), "M1", "VibrationRms", 1.83,
  datetime(2026-03-02 00:00:00), "M2", "VibrationRms", 2.41,
  datetime(2026-03-02 01:00:00), "M2", "VibrationRms", 2.38,
  datetime(2026-03-02 02:00:00), "M2", "VibrationRms", 2.44,
  datetime(2026-03-02 03:00:00), "M2", "VibrationRms", 2.40,
  datetime(2026-03-02 04:00:00), "M2", "VibrationRms", 2.43,
  datetime(2026-03-02 05:00:00), "M2", "VibrationRms", 2.39,
  datetime(2026-03-02 06:00:00), "M2", "VibrationRms", 2.45,
  datetime(2026-03-02 07:00:00), "M2", "VibrationRms", 2.42,
  datetime(2026-03-02 08:00:00), "M2", "VibrationRms", 2.40,
  datetime(2026-03-02 09:00:00), "M2", "VibrationRms", 2.44,
  datetime(2026-03-02 10:00:00), "M2", "VibrationRms", 2.38,
  datetime(2026-03-02 11:00:00), "M2", "VibrationRms", 2.41,
  datetime(2026-03-02 12:00:00), "M2", "VibrationRms", 2.43,
  datetime(2026-03-02 13:00:00), "M2", "VibrationRms", 2.40,
  datetime(2026-03-02 14:00:00), "M2", "VibrationRms", 2.45,
  datetime(2026-03-02 15:00:00), "M2", "VibrationRms", 2.39,
  datetime(2026-03-02 16:00:00), "M2", "VibrationRms", 2.42,
  datetime(2026-03-02 17:00:00), "M2", "VibrationRms", 2.44,
  datetime(2026-03-02 18:00:00), "M2", "VibrationRms", 2.41,
  datetime(2026-03-02 19:00:00), "M2", "VibrationRms", 2.40,
  datetime(2026-03-02 20:00:00), "M2", "VibrationRms", 2.43,
  datetime(2026-03-02 21:00:00), "M2", "VibrationRms", 2.38,
  datetime(2026-03-02 22:00:00), "M2", "VibrationRms", 2.42,
  datetime(2026-03-02 23:00:00), "M2", "VibrationRms", 2.44
];
// ---------------------------------------------------------------------------
MachineTelemetry
| where Signal == "VibrationRms" and Timestamp >= fromTime and Timestamp < toTime
// default=double(null) keeps gaps as null so they can be filled by interpolation instead of becoming a fake zero reading
| make-series Rms = avg(Value) default = double(null) on Timestamp from fromTime to toTime step binSize by MachineId
| extend Rms = series_fill_linear(Rms)
// Seasonality 0 = none (one day of data cannot show a weekly rhythm); use -1 to autodetect or 24 with 1h bins once you have weeks of data.
| extend (Flag, Score, Baseline) = series_decompose_anomalies(Rms, threshold, 0, 'avg')
| mv-expand Timestamp, Rms, Flag, Score, Baseline
| extend Timestamp = todatetime(Timestamp), Rms = todouble(Rms), Flag = toint(Flag), Score = todouble(Score), Baseline = todouble(Baseline)
| where Flag != 0
| project MachineId, Timestamp, Rms, Baseline = round(Baseline, 2), Score = round(Score, 1), Direction = iff(Flag > 0, "high", "low")
| order by MachineId asc, Timestamp asc
// Expected for the sample: the two disturbed hours of M1 are flagged high and M2 stays quiet (the spikes are far outside the
// noise). The decomposition is an algorithm, so check the result on your own data before you trust it: remove the 'where Flag != 0'
// line, filter to one machine and add '| project Timestamp, Rms, Baseline | render timechart' to see the series and its baseline.

// ==== Query B: z-score against a reference period ====
// ---- Parameters -----------------------------------------------------------
let trainEnd = datetime(2026-03-02 12:00:00);    // readings before this time define 'normal'
let zLimit   = 4.0;                              // flag when the reading is at least this many standard deviations above normal
let relLimit = 1.2;                              // and at least 20 percent above the reference mean
let MachineTelemetry = datatable(Timestamp:datetime, MachineId:string, Signal:string, Value:real) [
  datetime(2026-03-02 00:00:00), "M1", "VibrationRms", 1.82,
  datetime(2026-03-02 01:00:00), "M1", "VibrationRms", 1.79,
  datetime(2026-03-02 02:00:00), "M1", "VibrationRms", 1.85,
  datetime(2026-03-02 03:00:00), "M1", "VibrationRms", 1.81,
  datetime(2026-03-02 04:00:00), "M1", "VibrationRms", 1.78,
  datetime(2026-03-02 05:00:00), "M1", "VibrationRms", 1.84,
  datetime(2026-03-02 06:00:00), "M1", "VibrationRms", 1.80,
  datetime(2026-03-02 07:00:00), "M1", "VibrationRms", 1.83,
  datetime(2026-03-02 08:00:00), "M1", "VibrationRms", 1.79,
  datetime(2026-03-02 09:00:00), "M1", "VibrationRms", 1.82,
  datetime(2026-03-02 10:00:00), "M1", "VibrationRms", 1.85,
  datetime(2026-03-02 11:00:00), "M1", "VibrationRms", 1.81,
  datetime(2026-03-02 12:00:00), "M1", "VibrationRms", 1.80,
  datetime(2026-03-02 13:00:00), "M1", "VibrationRms", 1.84,
  datetime(2026-03-02 14:00:00), "M1", "VibrationRms", 1.78,
  datetime(2026-03-02 15:00:00), "M1", "VibrationRms", 1.83,
  datetime(2026-03-02 16:00:00), "M1", "VibrationRms", 1.81,
  datetime(2026-03-02 17:00:00), "M1", "VibrationRms", 4.92,
  datetime(2026-03-02 18:00:00), "M1", "VibrationRms", 4.35,
  datetime(2026-03-02 19:00:00), "M1", "VibrationRms", 1.82,
  datetime(2026-03-02 20:00:00), "M1", "VibrationRms", 1.80,
  datetime(2026-03-02 21:00:00), "M1", "VibrationRms", 1.84,
  datetime(2026-03-02 22:00:00), "M1", "VibrationRms", 1.79,
  datetime(2026-03-02 23:00:00), "M1", "VibrationRms", 1.83,
  datetime(2026-03-02 00:00:00), "M2", "VibrationRms", 2.41,
  datetime(2026-03-02 01:00:00), "M2", "VibrationRms", 2.38,
  datetime(2026-03-02 02:00:00), "M2", "VibrationRms", 2.44,
  datetime(2026-03-02 03:00:00), "M2", "VibrationRms", 2.40,
  datetime(2026-03-02 04:00:00), "M2", "VibrationRms", 2.43,
  datetime(2026-03-02 05:00:00), "M2", "VibrationRms", 2.39,
  datetime(2026-03-02 06:00:00), "M2", "VibrationRms", 2.45,
  datetime(2026-03-02 07:00:00), "M2", "VibrationRms", 2.42,
  datetime(2026-03-02 08:00:00), "M2", "VibrationRms", 2.40,
