let fromDay      = datetime(2026-02-20);
let toDay        = datetime(2026-03-02);        // exclusive: 10 daily bins (20 Feb to 1 Mar)
let minSlopeDay  = 0.05;                        // flag when |slope| is at least this much per day (sensor units per day)
