  datetime(2026-02-23 12:00:00), "OVEN-1", "TC-B", 179.8,
  datetime(2026-02-24 12:00:00), "OVEN-1", "TC-A", 180.2,
  datetime(2026-02-24 12:00:00), "OVEN-1", "TC-B", 179.9,
  datetime(2026-02-25 12:00:00), "OVEN-1", "TC-A", 180.0,
  datetime(2026-02-25 12:00:00), "OVEN-1", "TC-B", 179.6,
  datetime(2026-02-26 12:00:00), "OVEN-1", "TC-A", 179.9,
  datetime(2026-02-26 12:00:00), "OVEN-1", "TC-B", 179.4,
  datetime(2026-02-27 12:00:00), "OVEN-1", "TC-A", 180.1,
  datetime(2026-02-27 12:00:00), "OVEN-1", "TC-B", 179.5,
  datetime(2026-02-28 12:00:00), "OVEN-1", "TC-A", 180.0,
  datetime(2026-02-28 12:00:00), "OVEN-1", "TC-B", 179.3,
  datetime(2026-03-01 12:00:00), "OVEN-1", "TC-A", 180.1,
  datetime(2026-03-01 12:00:00), "OVEN-1", "TC-B", 179.2,
