SensorReadings
| where Timestamp >= fromDay and Timestamp < toDay
| summarize A = avgif(Value, SensorId == "TC-A"), B = avgif(Value, SensorId == "TC-B") by AssetId, Day = bin(Timestamp, 1d)
| where isnotnull(A) and isnotnull(B)
| extend DayDelta = A - B
// default=double(null) leaves missing days empty; series_fill_linear interpolates them instead of treating them as 0
| make-series Delta = avg(DayDelta) default = double(null) on Day from fromDay to toDay step 1d by AssetId
